#!/usr/bin/env bash
# loop351 = 200k blocks, 7 keys on one layer, 50 ms pacing: the base, check-before-slot alone (S1), 64 build threads (T64) and the merge at shards_ready (S3), then a step-down of the best. usage: run-loop351.sh <a|b|c|d>
# Stage a: WARM (60 ms), BP50, S1P50, S1P50T64, S13P50, S13P50T64, BP50b.  b: WARM, then 45 and 40 ms for the best stage-a configuration (window 1 at least 1.5% over max(BP50, BP50b), each step only while gate340 holds), else S1P50b and S1P50T64b.
# Same gates as loop346: build and test gate, free-space gate 120G a leg, 75-minute claim cap per stage, per-leg timeout 600 s, claim released on exit, datadirs wiped at the end. Launch: setsid nohup bash target/fleet-runs/launch-loop351.sh <stage> > target/fleet-runs/loop351<stage>.out 2>&1 &
WT=${LOOP351_WT:-/data/n42-build/wt338}; STAGE=${1:-a}
cd $WT
S=$WT/target/fleet-runs; [ "${LOOP351_DRY:-0}" = 1 ] && S=${LOOP351_S:-/tmp/loop351-dry} && mkdir -p $S
B=/data/blockchain/rust-fleet7-bench
# THE IMPORT-ONCE SWITCH. The registry (bin/n42, `ImportOnce`) is being added by another agent; N42_IMPORT_ONCE=1 is the expected
# name. Every leg but WARM passes it as $ONCE. Change it here, and only here, if the switch is named differently.
ONCE=N42_IMPORT_ONCE=1
export F7_NODES=7 F7_VALIDATORS=7 F7_CORES_PER_NODE=32 F7_PROFILE=bench F7_ROOT=/data/blockchain/rust-fleet7-bench F7_GENESIS=$WT/crates/chainspec/res/genesis/n42_fleet7_bench.json
NEW=$WT/target/deferred/release
NAT=$WT/target/native/release
UPG=/data/n42-build/upgrade-native/release
SIMD=$WT/target/native-simd/release
CLAIM=/data/blockchain/.box-claim-rust; CLAIM2=/data/blockchain/wr-logs/.box-claim-rust
cleanup() {
  # a dry run (LOOP351_DRY=1) owns no fleet: on 2026-10-08 a dry run of stage c, exited while stage a held the box, killed the running leg (S13P50) through this trap
  [ "${LOOP351_DRY:-0}" = 1 ] && return 0
  rm -f $CLAIM $CLAIM2
  # The fleet this runner started goes with it. Killing the runner alone left
  # seven nodes and seven validators running for four and a half hours on
  # 2026-09-19: they held the box against this runner's own quiet check and
  # against whoever claimed it next.
  for p in $(pgrep -f '/n4[2] node --chain'; pgrep -f 'h2_validato[r]'; pgrep -f 'tx_floo[d]'); do kill $p 2>/dev/null; done
}
trap cleanup EXIT
[ -n "${LOOP351_NAT:-}" ] && NAT=$LOOP351_NAT   # a dry run from another checkout plans with the real binaries
if [ "${LOOP351_DRY:-0}" != 1 ]; then
if ! grep -q 'N42_ENGINE_EXEC_CACHE' crates/n42/qmdb-reth/src/exec_cache.rs || ! grep -q 'N42_SETTLEMENT_TAGS' crates/n42/h2-execution/src/settlement.rs || ! grep -q 'fn vote_before_slot' crates/n42/h2-execution/src/driver.rs || ! grep -q 'F7_PIN_SWAP' scripts/fleet7-env.sh || ! grep -q 'fn parse_in_flight' crates/n42/h2-execution/src/driver.rs || ! grep -q 'held_at_arrival' bin/n42/src/follower_import.rs crates/n42/h2-execution/src/driver.rs || ! grep -q 'fn push_reverted' crates/n42/tx-queue/src/lib.rs || ! grep -q 'fn fold_runs' bin/n42/src/follower_import.rs || ! grep -q 'fn commit_fcu_async' crates/n42/h2-execution/src/driver.rs || ! grep -q 'f7_check_validator_count' scripts/fleet7-env.sh || ! grep -q 'fn recovered_by_hashes' crates/n42/tx-queue/src/lib.rs || ! grep -q 'fn free_async' crates/n42/engine-types/src/parallel_transfer.rs || ! grep -q 'fn senders_from_queue' crates/n42/tx-queue/src/lib.rs || ! grep -q 'parent_engine_wait' bin/n42/src/payload_serve.rs || ! grep -q 'fn ancestry_of' bin/n42/src/follower_import.rs || ! grep -q 'root_wait' bin/n42/src/payload_serve.rs || ! grep -q 'fn seal_shortfall' crates/n42/engine-types/src/payload.rs || ! grep -q 'fn gate_len' crates/n42/tx-queue/src/lib.rs || [ ! -r crates/n42/engine-types/src/canonical_head.rs ] || ! grep -q 'fn with_park_lanes' crates/n42/tx-queue/src/lib.rs || ! grep -q 'fn pruned_through' crates/n42/tx-queue/src/lib.rs || ! grep -q 'N42_BUILD_SKIP_DECIDED' crates/n42/engine-types/src/payload.rs || ! grep -q 'N42_STATE_AFTER_PULL' crates/n42/engine-types/src/payload.rs || ! grep -q 'N42_GRAFT_PREFAULT' crates/n42/engine-types/src/parallel_transfer.rs || grep -q 'refuse_stale_parent() {\s*$' /dev/null || ! grep -q 'replay_ms' crates/n42/qmdb-reth/src/node_state.rs || ! grep -q 'leader loop between commit and preamble' crates/n42/h2-node/src/service.rs || [ ! -r crates/chainspec/res/genesis/n42_fleet7_bench.json ] || ! grep -q 'F7_EL_MAP' scripts/fleet7-env.sh || ! grep -q 'F7_VAL_CPUS' scripts/fleet7-env.sh || ! grep -rq 'N42_IMPORT_ONCE' bin/n42/src crates/n42 || ! grep -q 'other_ms' bin/n42/src/follower_import.rs || ! grep -q 'fn own_block_imported' crates/n42/h2-execution/src/driver.rs || ! grep -q 'fn take_chained' crates/n42/h2-el-rpc/src/engine.rs || ! grep -q 'fn parent_executed_fields_or_built' crates/n42/engine-types/src/hotstuff_consensus.rs || ! grep -q 'fn state_at_soon' crates/n42/engine-types/src/direct_build.rs || ! grep -q 'fn convert_compact_body_to_block' crates/n42/engine-types/src/engine_validator.rs || ! grep -q 'fn get_by_hashes' crates/n42/tx-queue/src/lib.rs || ! grep -q 'fn index_and_stage' crates/n42/tx-queue/src/lib.rs || ! grep -q 'NEED_TXNS' crates/n42/h2-execution/src/raw_engine.rs || ! grep -q 'gate_forced' crates/n42/tx-ingest/src/lib.rs || ! grep -q 'fn import_for_validator' bin/n42/src/payload_serve.rs || ! grep -q 'FOREIGN_BODY' crates/n42/h2-execution/src/raw_engine.rs || ! grep -q 'fn note_reader_lag' crates/n42/qmdb-reth/src/node_state.rs || ! grep -q 'fn two_roads' bin/n42/src/follower_import.rs || ! grep -q 'fn follower_graft_stream' crates/n42/engine-types/src/parallel_transfer.rs || ! grep -q 'fn sort_reverts' crates/n42/engine-types/src/parallel_transfer.rs || ! grep -q 'fn graft_stream' crates/n42/engine-types/src/parallel_transfer.rs || ! grep -q 'install_staged' crates/n42/engine-types/src/payload.rs || ! grep -q 'fn direct_receipts_enabled' crates/n42/engine-types/src/payload.rs || ! grep -q 'tx_count += executed_count as u64' crates/n42/engine-types/src/payload.rs || ! grep -q 'fn batch_equation_holds' crates/n42/tx-types/src/alt_sig.rs || ! grep -q 'spawn_scoped(scope, root_job)' bin/n42/src/follower_import.rs || ! grep -q 'f7_fleet_cpus' scripts/fleet7-env.sh || ! grep -q 'f7_trace_of' scripts/fleet7-env.sh || [ ! -r crates/chainspec/res/genesis/n42_fleet7_bench_v21.json ] || [ ! -r crates/chainspec/res/genesis/n42_fleet7_bench_v99.json ] || [ ! -r scripts/fleet7-runs/manykeys350.py ] || ! grep -q N42_DEFERRED_IN_FLIGHT crates/n42/h2-execution/src/driver.rs || ! grep -q N42_BUILT_KEEP crates/n42/engine-types/src/built_executions.rs || ! grep -q N42_QMDB_RENAME_DEFER crates/n42/engine-types/src/chain_alias.rs || ! grep -q N42_HANDOFF_HEAD_MOVE bin/n42/src/payload_serve.rs || ! grep -q N42_HANDOFF_NO_CLONE crates/n42/engine-types/src/built_executions.rs || ! grep -q N42_HANDOFF_MOVE_BODY crates/n42/engine-types/src/built_executions.rs || ! grep -q N42_CANON_NOTIFY_LEAN crates/chain-state/src/in_memory.rs || ! grep -q N42_QUEUE_OFFLOCK crates/n42/tx-queue/src/lib.rs || ! grep -q N42_QMDB_COMPUTE_OFFLOCK crates/n42/qmdb-reth/src/node_state.rs || ! grep -q N42_QMDB_PERSIST_BATCH crates/n42/qmdb-reth/src/node_state.rs || ! grep -q N42_QUEUE_PLAN_SNAPSHOT crates/n42/tx-queue/src/snapshot.rs; then echo "INSTRUMENTATION MISSING in the working tree; nothing built"; echo ALLDONE; exit 1; fi
T=$S/tests-loop351.log; : > $T
BUILD_FROM=$(date -u +%s)
# the 40G scope needs the user systemd manager; when its bus is gone (it was, after claim a on 2026-10-08) run the test plain: the tests fit the box
tst() { echo "== $*" >> $T; if systemd-run --user --scope -q true >/dev/null 2>&1; then nice -n 19 systemd-run --user --scope -q -p MemoryMax=40G -p MemorySwapMax=0 "$@" >> $T 2>&1; else nice -n 19 "$@" >> $T 2>&1; fi; }
echo "tests from $(date +%H:%M) (no claim)"
SKIPGATE=""; if [ -n "${LOOP351_GATE_TREES:-}" ] && [ "$LOOP351_GATE_TREES" = "$(git rev-parse HEAD:crates)-$(git rev-parse HEAD:bin)" ]; then SKIPGATE=1; echo "test and build gate skipped: git diff --stat f2794a821 HEAD -- crates bin is empty (crates/ and bin/ unchanged since claim a build; LOOP351_GATE_TREES)"; fi
if [ -z "$SKIPGATE" ]; then
for spec in "-p n42-engine-types --lib direct_build" "-p n42-engine-types --lib payload" "-p n42-engine-types --lib output_shards" "-p n42-engine-types --test output_shards" "-p n42-tx-queue --lib" "-p n42-engine-types --lib frame" "-p n42-tx-types --lib" "-p n42-qmdb-reth --lib -- --test-threads=1" "-p n42-h2-execution --lib driver" "-p n42-h2-execution --test consensus_execution_loop" "-p n42 --lib payload_serve::tests" "-p n42 --lib follower_import" "-p n42-h2-el-rpc --lib" "-p n42-engine-types --lib engine_validator" "-p n42-h2-el-rpc --test build_chain" "-p n42-h2-consensus --lib header_profile" "-p n42-engine-types --lib chain_alias" "-p n42-engine-types --lib engine_validator" "-p n42-h2-consensus --lib compact_body" "-p n42-h2-node --lib body_channel" "-p n42-h2-net --lib rpc" "-p n42-engine-types --lib hotstuff_consensus" "-p n42-h2-execution --lib raw_engine" "-p n42-qmdb-reth --lib hotstuff" "-p n42-engine-types --lib payload" "-p n42-qmdb-reth --lib -- --test-threads=1" "-p n42-qmdb-reth --lib -- --test-threads=1" "-p n42-tx-ingest" "-p n42-tx-queue" "-p n42-h2-node --lib" "-p n42-h2-node --test four_node_fleet" "-p n42-h2-consensus --lib block_body" "-p n42-h2-execution --lib" "-p n42-h2-execution --test vote_before_slot" "-p n42-h2-el-rpc --test compact_channel" "-p n42-h2-execution --test settlement_tags" "-p n42-qmdb-reth --lib exec_cache" "-p n42-twig-core --lib" "-p n42-h2-consensus" "-p n42-h2-execution" "-p n42-h2-node" "-p n42-h2-el-rpc" "-p n42-qmdb-reth -- --test-threads=1" "-p n42-testing" "-p n42-engine-types --lib -- --test-threads=1" "-p n42 --lib -- --test-threads=1"; do
  # a_block_behind_busy_slots_is_voted_for_on_its_check_only_answer (h2-execution, check_before_slot) orders two concurrent imports' votes and fails about 1 run in 6 under load (2026-10-08, 4 of 12 gate runs): a failed spec is run up to 3 times
  ok=0; for try in 1 2 3; do if tst cargo test -j8 --target-dir target/deferred $spec; then ok=1; break; fi; echo "test spec failed (try $try of 3): $spec"; done
  if [ $ok = 0 ]; then echo "TESTS FAILED: $spec (see $T)"; echo ALLDONE; exit 1; fi
done
if ! tst cargo clippy -j8 --target-dir target/deferred -p n42-h2-el-rpc -p n42-h2-consensus -p n42-h2-execution -p n42-h2-node -p n42-engine-types -p n42-qmdb-reth -p n42-tx-types -p n42 --lib --bins; then echo "CLIPPY FAILED (see $T)"; echo ALLDONE; exit 1; fi
echo "tests passed at $(date +%H:%M): $(grep -E '^test result:' $T | sed -E 's/test result: ok. ([0-9]+) passed.*/\1/' | paste -sd+ | bc) tests"
if ! nice -n 19 cargo build -j8 --release --target-dir target/deferred -p n42 --bin n42 -p n42-h2-node --example h2_validator --example tx_flood --example h2_keygen --example send_tx > $S/build-loop351.log 2>&1; then echo "BUILD FAILED"; echo ALLDONE; exit 1; fi
echo "built $(git rev-parse --short HEAD)+tree at $(date +%H:%M)"
fi
WAITED_FROM=$(date -u +%s)
good() { local cpus; cpus=$(nproc)
  [ "$(pgrep -fc 'bin/n42-[a-z]+ --chai[n]')" = "0" ] && [ "$(pgrep -fc 'n42-[a-z0-9]+ --chai[n]')" = "0" ] \
    && [ "$(pgrep -fc '/n4[2] node --chain')" = "0" ] && [ "$(pgrep -fc 'n42-dat[c]')" = "0" ] && [ "$(pgrep -fc 'eth-el-frame[d]')" = "0" ] \
    && { [ "$(pgrep -fc 'txfloo[d]')" = "0" ] || [ $(( $(date -u +%s) - ${WAITED_FROM:-0} )) -gt 600 ]; } \
    && [ "$(free -g | awk '/Mem:/{print $7}')" -ge 80 ] \
    && [ "$(awk '{printf "%d", $1}' /proc/loadavg)" -lt $(( cpus / 4 )) ]; }
theirs_claim() { local f n=""; for f in /data/blockchain/.box-claim-* /data/blockchain/wr-logs/.box-claim-*; do [ -e "$f" ] || continue; case "$f" in *box-claim-rust) continue;; esac; v=$(tr -c '0-9\n' ' ' < "$f" | tr -s ' ' '\n' | grep -E '^[0-9]+$' | sort -n | tail -1); [ -z "$v" ] && v=9999999999; [ "$v" != 9999999999 ] && [ $(( $(date -u +%s) - v )) -gt 5400 ] && { echo "ignoring a claim older than 90 minutes: $f ($v)" >&2; continue; }; n="$n $v"; done; echo $n | tr ' ' '\n' | grep -E '^[0-9]+$' | sort -n | tail -1; }
quiet() { local n=0; while [ $n -lt 3 ]; do [ -z "$(theirs_claim)" ] || return 1; good || return 1; n=$((n+1)); [ $n -lt 3 ] && sleep 30; done; return 0; }
mkdir -p /data/blockchain/wr-logs
echo "waiting for a quiet box from $(date +%H:%M)"
while true; do
  until quiet; do sleep 30; done
  mine=$(date -u +%s); echo "$mine" | tee $CLAIM > $CLAIM2
  sleep $((20 + RANDOM % 31))
  theirs=$(theirs_claim)
  [ -n "$theirs" ] && [ "$theirs" -lt "$mine" ] && [ $(( mine - theirs )) -gt 5400 ] && theirs=""
  if good && { [ -z "$theirs" ] || [ "$theirs" -gt "$mine" ]; }; then break; fi
  rm -f $CLAIM $CLAIM2; echo "stood down at $(date +%H:%M): another claim or the box got busy"; sleep 60
done
echo "claimed at $(date +%H:%M) ($mine): avail $(free -g | awk '/Mem:/{print $7}')G load $(awk '{print $1}' /proc/loadavg)"
CLAIMED_AT=$(date -u +%s)
# A binary older than this runner's build is fine when cargo had nothing to relink (loop351: the same commit as the
# runner before it); what must not happen is a source file newer than the binary.
echo "tip $(git rev-parse --short HEAD) tree: $(git status --short | wc -l) changed files; native n42 built $(date -r $NAT/n42 +%H:%M:%S), h2_validator $(date -r $NAT/examples/h2_validator +%H:%M:%S), deferred n42 $(date -r $NEW/n42 +%H:%M:%S); last source change $(date -r "$(find crates bin scripts -name '*.rs' -o -name '*.sh' | xargs ls -t | head -1)" +%H:%M:%S) ($(find crates bin -name '*.rs' | xargs ls -t | head -1))"
if [ -n "$(find crates bin -name '*.rs' -newer $NAT/n42 | head -1)" ]; then echo "a source file is newer than the native binary the legs run; released without a leg"; echo ALLDONE; exit 1; fi
if [ -n "$(find crates bin -name '*.rs' -newer $NEW/n42 | head -1)" ]; then echo "a source file is newer than the binary; released without a leg"; echo ALLDONE; exit 1; fi

fi
[ "${LOOP351_DRY:-0}" = 1 ] && CLAIMED_AT=$(date -u +%s)
# --- the 400M replay set, generated by loop333 (docs 10.80)
REPLAY=/data/n42-pregen/g900000-400m; export F7_SENDERS_ARG=12500
if [ "${LOOP351_DRY:-0}" = 1 ]; then [ -f $REPLAY/.complete ] || echo "(dry) the 400M replay set is missing: $REPLAY/.complete"; else [ -f $REPLAY/.complete ] || { echo "the 400M replay set is missing ($REPLAY/.complete); released without a leg"; echo ALLDONE; exit 1; } fi
echo "replay set for every leg: $REPLAY (senders $F7_SENDERS_ARG)"
echo $REPLAY > $S/replay-loop351.txt; echo $F7_SENDERS_ARG > $S/senders-loop351.txt
export F7_LEADER_TENURE=16 F7_INGEST=1 F7_INGEST_ALL=1 F7_NO_TX_GOSSIP=1 N42_TX_INGEST_ASYNC=1
export F7_DIRECT_PUSH=1 F7_BLOCK_INTERVAL_MS=250 F7_SKIP_STALE_CHECK=1 F7_METRICS_BASE=19300 N42_TX_QUEUE=1
export N42_TX_INGEST_RECOVER_NICE=10 N42_TX_INGEST_RECOVER_PARALLEL=8 N42_TX_INGEST_DIRECT=1
elpid() { ps -eo pid,args | grep -E '/n4[2] node' | grep -E 'rust-fleet7-bench/node2' | awk '{print $1}' | head -1; }
sample() { local tag=$1
  for i in $(seq 1 44); do
    echo "$(date +%H:%M:%S) $(ps -eo rss,args | awk '/\/n4[2] node/{n++; s+=$1; if($1>mx)mx=$1; if(mn==0||$1<mn)mn=$1} /h2_validato[r]/{v+=$1} /tx_floo[d]/{f+=$1} END{printf "el_sum=%.1fG el_max=%.1fG el_min=%.1fG el_n=%d val_sum=%.1fG flood=%.1fG", s/1e6, mx/1e6, mn/1e6, n, v/1e6, f/1e6}') $(awk '/^MemAvailable|^MemFree|^AnonPages|^AnonHugePages|^Cached:|^Shmem:|^Slab:|^SUnreclaim|^PageTables|^Dirty:/{printf "%s%.1fG ", $1, $2/1e6}' /proc/meminfo) tmpfs=$(df --output=used -BG /tmp | tail -1 | tr -d ' ') compact_stall=$(awk '/^compact_stall/{print $2}' /proc/vmstat) flood_t=$(tail -1 $B/bench-$tag/flood.log 2>/dev/null | grep -oE '\+ *[0-9]+s' | tr -d ' ')"
    sleep 5
  done
}
median() { sort -n | awk '{a[NR]=$1} END{print (NR ? a[int(NR/2)+1] : "-")}'; }
run() { local tag=$1; shift
  local EL_MAP=0,1,2,3,4,5,6; for kv in "$@"; do case "$kv" in F7_EL_MAP=*) EL_MAP=${kv#*=};; esac; done
  local GLEG=""; for kv in "$@"; do case "$kv" in F7_GENESIS=*) GLEG=${kv#*=};; esac; done
  local NV; NV=$(python3 -c "print(len('$EL_MAP'.split(',')))")
  local NEL FIRSTS ELIDX; NEL=$(python3 -c "print(max(int(x) for x in '$EL_MAP'.split(','))+1)")
  FIRSTS=$(python3 -c "m=[int(x) for x in '$EL_MAP'.split(',')]; print(*[m.index(e) for e in range(max(m)+1)])"); ELIDX=$(seq 0 $((NEL-1)))
  env "$@" F7_BIN=$NAT bash scripts/fleet7.sh plan > $S/plan-$tag.txt 2>&1; echo "plan $tag: exit $? ($NV validators, $NEL layer(s)): $(sed -n 1p $S/plan-$tag.txt | sed -E 's/map [0-9,]+, //'); $(grep -m1 '^# validators :' $S/plan-$tag.txt); $(grep -m1 '^# fleet ' $S/plan-$tag.txt); $(grep -c REFUSED $S/plan-$tag.txt) refusals"
  if [ "${LOOP351_DRY:-0}" = 1 ]; then return 0; fi
  for d in $B/node[0-9]*; do [ -d "$d" ] && [ "${d##*node}" -ge $NV ] && rm -rf "$d"; done   # a smaller fleet after a larger one: no stale logs of the larger one in the reports
  local F7_GASPRICE_ARG="" F7_RPCBATCH_ARG="" F7_OFFSET_ARG="" F7_CONC_ARG="" F7_GASCEIL_ARG="" F7_PERTX_ARG=""; for kv in "$@"; do case "$kv" in F7_GASPRICE_ARG=*) F7_GASPRICE_ARG=${kv#*=};; F7_CONC_ARG=*) F7_CONC_ARG=${kv#*=};; F7_RPCBATCH_ARG=*) F7_RPCBATCH_ARG=${kv#*=};; F7_OFFSET_ARG=*) F7_OFFSET_ARG=${kv#*=};; F7_GASCEIL_ARG=*) F7_GASCEIL_ARG=${kv#*=};; F7_PERTX_ARG=*) F7_PERTX_ARG=${kv#*=};; esac; done
  ( n=0; until grep -q 'funding' $B/bench-$tag/flood.log 2>/dev/null; do sleep 1; n=$((n+1)); [ $n -gt 300 ] && exit 0; done; sample $tag ) > $S/mem-$tag.txt &
  ( n=0; until grep -q 'funding' $B/bench-$tag/flood.log 2>/dev/null; do sleep 1; n=$((n+1)); [ $n -gt 300 ] && exit 0; done; F7_ROOT=/data/blockchain/rust-fleet7-bench python3 $S/threadcpu4.py 200 ) > $S/threadcpu-$tag.tsv 2>/dev/null &
  ( n=0; until grep -q 'funding' $B/bench-$tag/flood.log 2>/dev/null; do sleep 1; n=$((n+1)); [ $n -gt 300 ] && exit 0; done; python3 scripts/fleet7-runs/threadcpu337.py sample 150 0 ) > $S/tidcpu-$tag.tsv 2>/dev/null &
  ( n=0; until grep -q 'funding' $B/bench-$tag/flood.log 2>/dev/null; do sleep 1; n=$((n+1)); [ $n -gt 300 ] && exit 0; done; for i in $FIRSTS; do p=$(ps -eo pid,args | grep '/n4[2] node' | grep "rust-fleet7-bench/node$i/" | grep -v grep | awk '{print $1}' | head -1); [ -n "$p" ] && timeout 60 perf stat -p $p -e page-faults,context-switches -I 5000 -x, -o $S/pf-$tag-node$i.csv >/dev/null 2>&1 & done; wait ) > /dev/null 2>&1 &
  ( n=0; until grep -q 'funding' $B/bench-$tag/flood.log 2>/dev/null; do sleep 1; n=$((n+1)); [ $n -gt 300 ] && exit 0; done; python3 scripts/fleet7-runs/valsample350.py sample $S/val-$tag.tsv 150 5 ) > /dev/null 2>&1 &
