  m=$(grep -a 'seal-first build phases' $f 2>/dev/null | grep -oE 'fields_mismatches=[0-9]+' | cut -d= -f2 | sort -n | tail -1)
  v=$(grep -a 'seal-first build phases' $f 2>/dev/null | grep -oE 'fields_verified=[0-9]+' | cut -d= -f2 | sort -n | tail -1)
  echo "FV gate: fields_verified=${v:-none} fields_mismatches=${m:-none}"
  if [ "${m:-x}" != 0 ] || [ "${v:-0}" -le 0 ]; then
    echo "FV FAILED (a mismatch, or no check was made): stopping the round"
    grep -a -E 'fields.*(mismatch|differ)' $f | head -8 | cut -c1-400
    for i in 0 1 2 3 4 5 6; do rm -rf $B/node$i/el $B/node$i/consensus; done
    cleanup; echo "released at $(date +%H:%M)"; echo ALLDONE; exit 1
  fi
}

leg() {
  if [ "${LOOP351_DRY:-0}" != 1 ] && [ $(( $(date -u +%s) - CLAIMED_AT )) -gt 4500 ]; then echo "leg loop351$1 skipped: 75 minutes of the claim used"; return; fi
  local tag=$1; shift
  printf '%q ' "$@" > $S/args-loop351$tag.txt
  eval "LA_${tag}=(\"\$@\")"
  local need=120; case $tag in E7*) need=450;; esac
  if [ "${LOOP351_DRY:-0}" != 1 ]; then case $tag in K99*) local memav; memav=$(free -g | awk '/Mem:/{print $7}'); if [ "${memav:-0}" -lt 75 ]; then echo "leg loop351$tag skipped: ${memav}G available, 99 validators need ~35G on top of the layer's 30G and a 40G huge-page pool"; return; fi;; esac; fi
  local avail; avail=$(df -BG /data | awk 'NR==2{gsub("G","",$4); print $4}')
  if [ "${LOOP351_DRY:-0}" != 1 ] && [ "${avail:-0}" -lt $need ]; then echo "leg loop351$tag skipped: /data has ${avail}G free, the leg needs $need G with margin"; return; fi
  echo "leg loop351$tag: /data free ${avail}G (needs $need G)"
  n=0; while [ "${LOOP351_DRY:-0}" != 1 ] && [ "$(awk '{printf "%d", $1}' /proc/loadavg)" -ge 8 ] && [ $n -lt 4 ]; do echo "load $(awk '{print $1}' /proc/loadavg) at $(date +%H:%M:%S), waiting"; sleep 30; n=$((n+1)); done
  run loop351$tag F7_MEASURE_FROM_LOG=1 F7_EL_EXTRA="--builder.interval 60 --builder.deadline 3" N42_FAST_TRANSFER=1 N42_FOLLOWER_DIRECT_IMPORT=1 F7_SENDER_CACHE_MULT=4 N42_TX_QUEUE_BATCH=1024 N42_TX_QUEUE_DRAINER=1 F7_FLOOD_WINDOW=6 N42_TX_INGEST_RECOVER_PARALLEL=12 F7_BLOCK_INTERVAL_MS=350 "$@"
}
C='N42_BUILDER_PULLER=1024 N42_TX_QUEUE_RUN=64 MALLOC_CONF=thp:always N42_FOLLOWER_PARALLEL=1 TOKIO_WORKER_THREADS=8 F7_FLOOD_ALG=ed25519 N42_ALTSIG_SENDER_CACHE=4194304 N42_ED25519_BATCH=128'
R='N42_PARALLEL_BUILD=1 N42_FOLLOWER_GRAFT=1 F7_STRAGGLER_GRACE_MS=600 RAYON_NUM_THREADS=16 N42_BUILD_ON_SEAL=1 F7_LEADER_TENURE=64 N42_QMDB_RETAIN_DEPTH=16 N42_QMDB_ENTRY_FILE=1'
A2='MALLOC_CONF=thp:always,oversize_threshold:0,dirty_decay_ms:2000,background_thread:true'
D='N42_QMDB_READS=on N42_HASHED_TABLES=off F7_BLOCK_INTERVAL_MS=275 F7_GASPRICE_ARG=1000000000000000000000000 F7_SENDER_CACHE_MULT=1'

jud() { python3 - $1 <<'PYEOF'
import re, subprocess, sys
t = sys.argv[1]; B = '/data/blockchain/rust-fleet7-bench'
try:
    r = open(f'{B}/bench-loop351{t}/round.txt').read()
    w = int(re.search(r'win1 +tps= *([\d,]+)', r)[1].replace(',', ''))
    m = re.search(r'win1 .*full\(>=95%\)=(\d+)/(\d+)', r); full = int(m[1]) / max(1, int(m[2]))
    out = subprocess.run(['python3', 'scripts/fleet7-runs/analyze328.py', f'loop351{t}'], capture_output=True, text=True).stdout
    m = re.search(r'seal ([\d.]+)%', out); seal = float(m[1]) / 100 if m else 0.0
    print(t, w, round(full, 3), round(seal, 3))
except Exception as e:
    print(t, 0, 0, 1)
PYEOF
}
argsof() { eval "$2=($(cat $S/args-loop351$1.txt))"; }

# a leg whose feed bound is rerun once with the feed raised (docs 10.82); the rerun's numbers are reported as such
# a prepared-body leg that produces a refused / invalid block (or a mismatch, an uncommitted own block, a given-up proposal) stops the round after that leg
bodygate() {
  local tag=$1 f=$B/bench-$1/node0-el.log inv gas fm nc gu
  inv=$(grep -ac 'Encountered invalid block' $f 2>/dev/null); gas=$(grep -ac 'gas used mismatch' $f 2>/dev/null)
  fm=$(grep -a 'seal-first build phases' $f 2>/dev/null | grep -oE 'fields_mismatches=[0-9]+' | cut -d= -f2 | sort -n | tail -1)
  nc=$(grep -ac 'was not the one committed' $f 2>/dev/null); gu=$(cat $B/bench-$1/node*-v.log 2>/dev/null | grep -ac 'could not build a block to propose')
  echo "bodygate $tag: invalid_blocks=${inv:-0} gas_mismatch=${gas:-0} fields_mismatches=${fm:-none} own_not_committed=${nc:-0} proposals_given_up=${gu:-0}"
  if [ "${inv:-0}" != 0 ] || [ "${gas:-0}" != 0 ] || [ "${fm:-0}" != 0 ] || [ "${nc:-0}" != 0 ] || { [ "${gu:-0}" != 0 ] && [ "${tag#K99}" = "${tag}" ] && [ "${tag#loop351K99}" = "${tag}" ]; }; then   # K99 legs give up 4-5 proposals each (a view that times out: counted and reported, not a stop; K99 stopped nothing but the last leg of a and b, and K99G0 follows K99P50)
    echo "BODYGATE FAILED on $tag: stopping the round (datadirs kept as evidence)"; cleanup; echo "released at $(date +%H:%M)"; echo ALLDONE; exit 1
  fi
}

# every depth-2 leg: fields_mismatches 0, invalid_blocks 0, no ParentUnknown, tc 1, fleet7-verify clean; rename_fallbacks and rename_record_waits are printed (a nonzero fallback count is reported, not a stop)
d2gate() {
  local tag=$1 f=$B/bench-$1/node0-el.log inv fm pu tc rf rw vp
  inv=$(grep -ac 'Encountered invalid block' $f 2>/dev/null); fm=$(grep -a 'seal-first build phases' $f 2>/dev/null | grep -oE 'fields_mismatches=[0-9]+' | cut -d= -f2 | sort -n | tail -1)
  pu=$(cat $B/bench-$1/node*-v.log $f 2>/dev/null | grep -ac 'ParentUnknown'); tc=$(cat $B/bench-$1/node*-v.log 2>/dev/null | grep -ac 'TC formed')
  rf=$(grep -a 'seal-first build phases' $f 2>/dev/null | grep -oE 'rename_fallbacks=[0-9]+' | cut -d= -f2 | paste -sd+ | bc); rw=$(grep -a 'seal-first build phases' $f 2>/dev/null | grep -oE 'rename_record_waits=[0-9]+' | cut -d= -f2 | paste -sd+ | bc)
  vp=$(python3 -c "import json; d=json.load(open('$B/bench-$1/verify.json')); print('pass' if d.get('pass') and not d.get('disagreements') else 'FAIL')" 2>/dev/null)
  echo "d2gate $tag: invalid_blocks=${inv:-0} fields_mismatches=${fm:-none} ParentUnknown=${pu:-0} TC_formed_lines=${tc:-0} verify=${vp:-none} rename_fallbacks_total=${rf:-0} rename_record_waits_total=${rw:-0}"
  if [ "${inv:-0}" != 0 ] || [ "${fm:-0}" != 0 ] || [ "${pu:-0}" != 0 ] || [ "${vp:-none}" != pass ] || [ "${tc:-0}" -gt 1 ]; then
    echo "D2GATE FAILED on $tag: stopping the round (datadirs kept as evidence)"; cleanup; echo "released at $(date +%H:%M)"; echo ALLDONE; exit 1
  fi
}

legf() {
  local tag=$1; shift
  leg $tag "$@"
  [ -f $B/bench-loop351$tag/round.txt ] || return
  python3 scripts/fleet7-runs/feedcheck335.py loop351$tag; python3 scripts/fleet7-runs/feed337.py loop351$tag 2>&1 | cut -c1-420; python3 scripts/fleet7-runs/feed338.py loop351$tag 2>&1 | cut -c1-900; python3 scripts/fleet7-runs/prune337.py loop351$tag 2>&1 | cut -c1-400; python3 scripts/fleet7-runs/plan339.py loop351$tag 2>&1 | cut -c1-420; python3 scripts/fleet7-runs/persist340.py loop351$tag 2>&1 | cut -c1-900; python3 scripts/fleet7-runs/fields346.py loop351$tag 2>&1 | cut -c1-4200; python3 scripts/fleet7-runs/voteroad346.py loop351$tag 2>&1 | cut -c1-420; python3 scripts/fleet7-runs/threadcpu337.py report $S/tidcpu-loop351$tag.tsv 2>&1 | cut -c1-300; python3 scripts/fleet7-runs/fields336.py loop351$tag 2>&1 | cut -c1-900
  case "$*" in *PLAN_AHEAD_BODY=1*) bodygate loop351$tag ;; esac
  case "$*" in *n42_fleet7_bench_d2*) d2gate loop351$tag ;; esac
}


# --- the legs
# The base: loop345 ALL, verbatim (E=1: F7_EL_MAP all zeros, the import-once registry, 200k transfers, 60 ms, depth 1). What a leg changes is
# appended AFTER it, so the later assignment wins: the key count, the chain, the CPU budget and the traced validators.
ALLA=(F7_BIN=$NAT RETH_ENGINE_NUM_STATE_MASKING_BLOCKS=0 $C $R $D $A2 "F7_EL_EXTRA=--builder.interval 60 --builder.deadline 3 --prune.transaction-lookup.full" N42_BUILD_CHAIN=1 N42_COMMIT_FCU_ASYNC=1 N42_BODY_ONCE=1 F7_BENCH_POOL_SLOTS=2000000 F7_BLOCK_INTERVAL_MS=60 N42_FOLLOWER_PARTITION_HASH=1 N42_FOLLOWER_FREE_ASYNC=1 F7_LEADER_TENURE=256 F7_PERTX_ARG=32000 N42_BLOCK_BY_DESCRIPTION=1 N42_BUILD_COLLECT_IN_PLACE=1 N42_BUILD_ON_OUTPUT=1 N42_SEAL_AT_EXEC=1 N42_STATE_AFTER_PULL=1 N42_FOLLOWER_PARTITION_AHEAD=1 N42_ENGINE_TAKE_SEALED=1 TOKIO_WORKER_THREADS=16 N42_BUILD_START_ASYNC=1 F7_BLOCK_INTERVAL_MS=60 F7_BENCH_POOL_SLOTS=2000000 F7_FLOOD_RATE=4000000 F7_LEADER_TENURE=1024 N42_TENURE_FIRST_ON_OUTPUT=1 N42_ED25519_BATCH=256 N42_FRAME_BLOCKS=1 F7_FLOOD_GATEWAY_KEY=seed:n42-bench-gateway N42_FRAME_GATEWAYS=0x87f7d242c742c0990ded1018a88b1296dbd89adbab9dff0bda008678beb2aa12 N42_FRAME_ATTEST_MIN=1 N42_OUTPUT_SHARDS=16 N42_OUTPUT_INDEX=1 F7_BLOCK_INTERVAL_MS=60 N42_FOLLOWER_FIELDS_EARLY=1 N42_FOLLOWER_EXEC_EARLY=1 N42_FOLLOWER_BUILD_PATH=1 N42_FOLLOWER_ROOT_ON_BUILD_POOL=1 N42_OUTPUT_INDEX_LIVE=1 N42_FOLLOWER_FRAME_SCAN=1 F7_BLOCK_INTERVAL_MS=60 N42_PARALLEL_BUILD_THREADS=32 N42_FOLLOWER_COPY_ASIDE=1 N42_STORAGE_OP_METRICS=0 N42_TAKE_COMPACT=1 N42_COMPACT_BODY=1 N42_BUILD_THROTTLE_SOFT=48 N42_BUILD_THROTTLE_HARD=80 N42_ACCOUNT_HISTORY=off F7_FLOOD_REPLAY=$REPLAY F7_OFFSET_ARG=900000 N42_SETTLEMENT_TAGS=legacy F7_EL_MAP=0,0,0,0,0,0,0 $ONCE F7_GASCEIL_ARG=4200000000 N42_LEADER_LAYERS=3 N42_FIELDS_AT_SEAL=1 F7_FLOOD_RATE=6000000 F7_BENCH_POOL_SLOTS=3000000 N42_ROAD_RUNTIME=1 N42_TX_INGEST_RECOVER_PARALLEL=24 N42_TX_QUEUE_DRAIN_CHUNK=8192 N42_PLAN_AHEAD=1 N42_PULL_BY_FRAMES=1 N42_ANSWER_LAYOUT_ONLY=1 N42_SF_PARALLEL_ENCODE=1 N42_SF_EARLY_WRITEBACK=1 N42_PERSIST_QMDB_IN_SCOPE=1 N42_LIVE_INDEX_DEFER=1 N42_FREEZE_AFTER_SEAL=1 N42_ROOT_OPS_AHEAD=1 N42_SEAL_ON_COUNTERS=1 N42_PLAN_AHEAD_BODY=1 N42_BUILD_BATCHES=128 N42_FREEZE_POOL=own)
GEN=$WT/crates/chainspec/res/genesis
zeros() { python3 -c "print(','.join(['0']*$1))"; }
# kv N VAL_CPUS [genesis]: the many-key overrides. F7_FLEET_CPUS=224 keeps the node budget at 7 x 32 whatever the key count; the layer gets
# 224 - VAL_CPUS (K7 16 -> 208, as in loop345; K21 32 -> 192; K99 96 -> 128, estimated need ~100 cores for 99 validator loops, doc section 5).
# F7_TRACE_VALIDATOR=0,1,2: the validators that lead during a leg log every consensus message (one line each); the other 96 do not.
kv() { local n=$1 v=$2 g=${3:-$GEN/n42_fleet7_bench.json}; KV=(F7_GENESIS=$g F7_VALIDATORS=$n F7_NODES=$n "F7_EL_MAP=$(zeros $n)" F7_FLEET_CPUS=224 F7_VAL_CPUS=$v F7_TRACE_VALIDATOR=0,1,2); }
mk() { # mk TAG N VAL_CPUS [more args]: one leg on the base
  local tag=$1 n=$2 v=$3; shift 3
  local g=$GEN/n42_fleet7_bench.json; [ $n = 21 ] && g=$GEN/n42_fleet7_bench_v21.json; [ $n = 99 ] && g=$GEN/n42_fleet7_bench_v99.json
  kv $n $v $g; legf $tag "${ALLA[@]}" "${KV[@]}" F7_VAL_NO_MALLOC_CONF=1 "$@"
}
warm_gate() { local W=$B/bench-loop351$1; [ "${LOOP351_DRY:-0}" = 1 ] && return 0
  if grep -q 'REFUSING' $W/flood.log 2>/dev/null || ! grep -q 'replay *:' $W/flood.log 2>/dev/null || [ "$(grep -oE 'win1 +tps= *[0-9,]+' $W/round.txt | grep -oE '[0-9,]+$' | tr -d , | head -1)" -lt 100000 ]; then echo "REPLAY DID NOT RUN on $1: stopping"; grep -E 'REFUSING|replay' $W/flood.log | head -5 | cut -c1-300; echo ALLDONE; exit 1; fi; }
# the straggler rule shows in a K99 leg when >= 1% of the leader's consecutive proposal intervals are >= 500 ms (a grace that ran out is 600 ms)
straggler_shows() { local f n
  for t in K99 K99b; do f=$S/manykeys-loop351$t.out; [ -f $f ] || continue
    n=$(grep -m1 'proposal interval' $f | sed -E 's/.*n=([0-9]+).*>= 500 ms: ([0-9]+).*/\1 \2/'); set -- $n
    [ -n "${2:-}" ] && [ "$1" -gt 0 ] && [ $(( $2 * 100 )) -ge "$1" ] && return 0; done
  [ -f $S/manykeys-loop351K99.out ] || [ -f $S/manykeys-loop351K99b.out ] || return 0   # no K99 report here (stage run alone): run it
  return 1; }

# claim 3 runs 99 keys only if the validators now fit: the first K99 leg's summed per-key RSS peak (valsample) must be under 30 GB, else the stage stops and the report says what a validator holds (valmem-<tag>.txt)
k99_rss_gate() { local tag=$1; [ "${LOOP351_DRY:-0}" = 1 ] && return 0
  local sum; sum=$(python3 -c "
import sys; sys.path.insert(0,'scripts/fleet7-runs'); import valsample350 as v, io, contextlib
b=io.StringIO()
with contextlib.redirect_stdout(b): v.report('$S/val-loop351$tag.tsv')
import re; m=re.search(r'sum of peaks ([0-9.]+) G', b.getvalue()); print(m[1] if m else 999)" 2>/dev/null)
  echo "K99 validator RSS gate: $tag validators hold ${sum:-?} G summed at their peaks (limit 30 G)"
  if [ "$(python3 -c "print(1 if float('${sum:-999}')>30 else 0)")" = 1 ]; then echo "K99 RSS GATE: the validators still hold more than 30 G; the other K99 legs are not run (see valmem-loop351$tag.txt)"; for i in $(seq 0 98); do rm -rf $B/node$i/el $B/node$i/consensus; done; cleanup; echo "released at $(date +%H:%M)"; echo ALLDONE; exit 0; fi; }
# loop351 = scope section 19: items 1-4 (S1 = + N42_CHECK_BEFORE_SLOT, S12 = + N42_LEADER_LAYERS=6, S123 = + the early merge, S1234 = + shards before receipts and the split freeze)
# on the base B = loop345 ALL + the vote-side gains of loop349 (aggregate verify, direct votes, gossip queue bound), 7 keys, E=1, 200k transfers, 60 ms.
VB="N42_VOTE_AGGREGATE_VERIFY=1 N42_VOTE_TRANSPORT=direct N42_GOSSIP_HANDLER_QUEUE=64 N42_GOSSIP_MAX_IHAVE=500"
S1="N42_CHECK_BEFORE_SLOT=1"; S2="N42_LEADER_LAYERS=6"; S3="N42_MERGE_AT_SHARDS_READY=1 N42_MERGE_POOL_THREADS=16"; S4="N42_SHARDS_BEFORE_RECEIPTS=1 N42_FREEZE_SPLIT=4"; T64="N42_PARALLEL_BUILD_THREADS=64"
VB="N42_VOTE_AGGREGATE_VERIFY=1 N42_VOTE_TRANSPORT=direct N42_GOSSIP_HANDLER_QUEUE=64 N42_GOSSIP_MAX_IHAVE=500"
b7() { local tag=$1; shift; mk $tag 7 16 $VB "$@"; }
# a configuration is NAME:SUFFIX (S1:, S1:T64, S13:, S13:T64); its flags and its leg tag at a pacing
cflags() { local f=""; case $1 in S1*) f="$S1";; S13*) f="$S1 $S3";; esac; case $1 in *T64) f="$f $T64";; esac; echo "$f"; }
ctag() { local c=$1 p=$2; case $c in *T64) echo "${c%T64}P${p}T64";; *) echo "${c}P${p}";; esac; }
# the next pacing step runs only while the previous step's cycle median is within 3 ms of its pacing and the backlog is flat (gate340.py: names the test that failed)
step() { local cur=$1 next=$2 cfg=$3; shift 3; local G tags=""; for t in "$@"; do tags="$tags loop351$t"; done
  if [ "${LOOP351_DRY:-0}" = 1 ]; then echo "(dry) gate at $cur ms assumed to hold"; b7 $(ctag $cfg $next) F7_BLOCK_INTERVAL_MS=$next $(cflags $cfg); return 0; fi
  if G=$(python3 scripts/fleet7-runs/gate340.py $cur $tags); then echo "gate at $cur ms ($*): $G"; b7 $(ctag $cfg $next) F7_BLOCK_INTERVAL_MS=$next $(cflags $cfg); return 0; fi
  echo "STEPS STOP before $next ms ($*): $G"; return 1; }
w1of() { grep -oE 'win1 +tps= *[0-9,]+' $B/bench-loop351$1/round.txt | grep -oE '[0-9,]+$' | tr -d , | tail -1; }
case $STAGE in
  a) mk WARM 7 16; warm_gate WARM
     b7 BP50 F7_BLOCK_INTERVAL_MS=50
     b7 S1P50 F7_BLOCK_INTERVAL_MS=50 $S1
     b7 S1P50T64 F7_BLOCK_INTERVAL_MS=50 $S1 $T64
     b7 S13P50 F7_BLOCK_INTERVAL_MS=50 $S1 $S3
     b7 S13P50T64 F7_BLOCK_INTERVAL_MS=50 $S1 $S3 $T64
     b7 BP50b F7_BLOCK_INTERVAL_MS=50 ;;
  b) mk WARM 7 16; warm_gate WARM
     # needs the stage-a round.txt files on disk: the best of the four configurations by window 1 must beat max(BP50, BP50b) by 1.5%
     WB1=$(w1of BP50); WB2=$(w1of BP50b)
     BASEW=$(python3 -c "print(max(int('${WB1:-0}' or 0), int('${WB2:-0}' or 0)))")
     BEST=""; BESTW=0
     for cfg in S1 S1T64 S13 S13T64; do W=$(w1of $(ctag $cfg 50)); echo "stage a window 1: $(ctag $cfg 50) ${W:-none}"; [ "${W:-0}" -gt "$BESTW" ] && { BEST=$cfg; BESTW=$W; }; done
     if [ "${LOOP351_DRY:-0}" = 1 ] && [ -z "$BEST" ]; then BEST=S1; BESTW=1; BASEW=0; echo "(dry) no stage-a data: planning the step-down of S1"; fi
     echo "stage a base window 1: BP50 ${WB1:-none}, BP50b ${WB2:-none}; best configuration ${BEST:-none} at ${BESTW}"
     if [ -n "$BEST" ] && [ "$(python3 -c "print(1 if $BESTW >= 1.015 * $BASEW and $BASEW > 0 or ($BASEW == 0 and $BESTW > 0 and '${LOOP351_DRY:-0}' == '1') else 0)")" = 1 ]; then
       echo "$BEST beats the base by 1.5% or more: stepping it down"
       if step 50 45 $BEST $(ctag $BEST 50); then step 45 40 $BEST $(ctag $BEST 45); fi
     else
       echo "no configuration beat the base by 1.5%: second legs of S1P50 and S1P50T64"
       b7 S1P50b F7_BLOCK_INTERVAL_MS=50 $S1
       b7 S1P50T64b F7_BLOCK_INTERVAL_MS=50 $S1 $T64
     fi ;;
  c) mk WARM 7 16; warm_gate WARM
     b7 S2P50T64 F7_BLOCK_INTERVAL_MS=50 $S2 $T64
     b7 S12P50T64 F7_BLOCK_INTERVAL_MS=50 $S1 $S2 $T64
     b7 S123P50T64 F7_BLOCK_INTERVAL_MS=50 $S1 $S2 $S3 $T64
     b7 S12P50T64b F7_BLOCK_INTERVAL_MS=50 $S1 $S2 $T64
     b7 S123P50T64b F7_BLOCK_INTERVAL_MS=50 $S1 $S2 $S3 $T64
     b7 S2P50T64b F7_BLOCK_INTERVAL_MS=50 $S2 $T64 ;;
  d) mk WARM 7 16; warm_gate WARM
     D2="F7_GENESIS=$WT/crates/chainspec/res/genesis/n42_fleet7_bench_d2.json"
     b7 S2P45T64 F7_BLOCK_INTERVAL_MS=45 $S2 $T64
     b7 D2S2P50T64 $D2 F7_BLOCK_INTERVAL_MS=50 $S2 $T64
     b7 D2S2P45T64 $D2 F7_BLOCK_INTERVAL_MS=45 $S2 $T64
     b7 D2S2P40T64 $D2 F7_BLOCK_INTERVAL_MS=40 $S2 $T64
     b7 D2S2P45T64b $D2 F7_BLOCK_INTERVAL_MS=45 $S2 $T64
     b7 D2S2P40T64b $D2 F7_BLOCK_INTERVAL_MS=40 $S2 $T64 ;;
  e) mk WARM 7 16; warm_gate WARM
     D2="F7_GENESIS=$WT/crates/chainspec/res/genesis/n42_fleet7_bench_d2.json"
     b7 D2S12P45T64 $D2 F7_BLOCK_INTERVAL_MS=45 $S1 $S2 $T64
     b7 D2S12P40T64 $D2 F7_BLOCK_INTERVAL_MS=40 $S1 $S2 $T64
     b7 D2S12P45T64b $D2 F7_BLOCK_INTERVAL_MS=45 $S1 $S2 $T64
     b7 D2S12P40T64b $D2 F7_BLOCK_INTERVAL_MS=40 $S1 $S2 $T64
     b7 D2S12P35T64 $D2 F7_BLOCK_INTERVAL_MS=35 $S1 $S2 $T64
     b7 D2S12P35T64b $D2 F7_BLOCK_INTERVAL_MS=35 $S1 $S2 $T64 ;;
  f) mk WARM 7 16; warm_gate WARM
     D2="F7_GENESIS=$WT/crates/chainspec/res/genesis/n42_fleet7_bench_d2.json"; F2="N42_FAR_AHEAD_BLOCKS=2"
     b7 D2S12F2P45T64 $D2 F7_BLOCK_INTERVAL_MS=45 $S1 $S2 $F2 $T64
     b7 D2S12F2P40T64 $D2 F7_BLOCK_INTERVAL_MS=40 $S1 $S2 $F2 $T64
     b7 D2S12F2P35T64 $D2 F7_BLOCK_INTERVAL_MS=35 $S1 $S2 $F2 $T64
     b7 D2S12F2P45T64b $D2 F7_BLOCK_INTERVAL_MS=45 $S1 $S2 $F2 $T64
     b7 D2S12F2P40T64b $D2 F7_BLOCK_INTERVAL_MS=40 $S1 $S2 $F2 $T64
     b7 D2S12F2P35T64b $D2 F7_BLOCK_INTERVAL_MS=35 $S1 $S2 $F2 $T64 ;;
  g) mk WARM 7 16; warm_gate WARM
     D2="F7_GENESIS=$WT/crates/chainspec/res/genesis/n42_fleet7_bench_d2.json"; F6="N42_FAR_AHEAD_BLOCKS=6"
     b7 D2S12F6P45T64 $D2 F7_BLOCK_INTERVAL_MS=45 $S1 $S2 $F6 $T64
